// Blink: count clock cycles and flip LEDR0 every half period.
module top #(
  parameter CLK_HZ   = 50_000_000,   // the board clock: cycles per second
  parameter BLINK_HZ = {{p:hz}}
) (
  input            MAX10_CLK1_50,
  output reg [9:0] LEDR
);
  // Clock cycles in half a blink.
  localparam HALF = CLK_HZ / (2 * BLINK_HZ);

  reg [31:0] count = 0;
  initial LEDR = 10'b0;

  always @(posedge MAX10_CLK1_50) begin
    if (count == HALF - 1) begin
      count   <= 0;
      LEDR[0] <= ~LEDR[0];                               // flip LEDR0
      if (LEDR[0]) LEDR[9:6] <= LEDR[9:6] + 1;           // LEDR0 is about to go off: one more blink
    end else begin
      count <= count + 1;
    end
  end
endmodule

